#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

REPO_ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
ANALYTICS_DIR="$REPO_ROOT/analytics"
ENV_FILE="$REPO_ROOT/.env"
WRANGLER=()

select_wrangler() {
  if command -v npx >/dev/null 2>&1; then
    WRANGLER=(npx --yes wrangler@4)
    return 0
  fi
  if command -v pnpm >/dev/null 2>&1; then
    WRANGLER=(pnpm dlx wrangler@4)
    return 0
  fi
  local codex_node_dir="${HOME:-}/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/bin"
  local codex_pnpm_bin="${HOME:-}/.cache/codex-runtimes/codex-primary-runtime/dependencies/bin/fallback/pnpm"
  if [[ -x "$codex_node_dir/node" && -x "$codex_pnpm_bin" ]]; then
    WRANGLER=(env "PATH=$codex_node_dir:/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin" "$codex_pnpm_bin" dlx wrangler@4)
    return 0
  fi
  return 1
}

run_wrangler() {
  (cd "$ANALYTICS_DIR" && "${WRANGLER[@]}" "$@")
}

verify_remote_without_public_url() {
  local deployments secrets name
  deployments=$(run_wrangler deployments list --json)
  [[ "$deployments" == *'"percentage": 100'* ]] || return 1

  secrets=$(run_wrangler secret list)
  for name in ADMIN_USERNAME ADMIN_PASSWORD IP_HASH_KEY; do
    [[ "$secrets" == *"\"name\": \"${name}\""* ]] || return 1
  done

  run_wrangler d1 execute DB --remote --command "SELECT 1 AS ok" --json >/dev/null
}

put_worker_secret() {
  local name="$1" value="$2"
  printf '%s' "$value" | run_wrangler secret put "$name"
}

banner "Visitor analytics · Cloudflare setup"

stage "Node.js and Wrangler"
say "Wrangler is Cloudflare's official deployment tool and runs on Node.js."
if ! select_wrangler; then
  open_url "https://nodejs.org/en/download"
  step "Install the current Node.js LTS release, then return to this terminal."
  pause "Press Enter after Node.js is installed."
  hash -r
fi
if ! select_wrangler; then
  warn "npx or pnpm is still unavailable. Re-run this wizard after installing Node.js."
  exit 1
fi
run_wrangler --version

stage "Authorize Cloudflare"
say "This uses browser-based OAuth. No Cloudflare password or API token is copied into the repository."
open_url "https://dash.cloudflare.com/"
if run_wrangler whoami >/dev/null 2>&1; then
  say "Wrangler is already signed in."
else
  step "Approve the Wrangler authorization request in the browser window that opens."
  run_wrangler login
fi
run_wrangler whoami

stage "Create and migrate D1"
say "D1 stores pseudonymous visitor records. Its database ID is public configuration, not a secret."
if grep -Eq '"database_id"[[:space:]]*:' "$ANALYTICS_DIR/wrangler.jsonc"; then
  say "A D1 binding already exists in wrangler.jsonc; keeping it."
else
  if ! confirm "Create the leeedwina430-github-io-analytics D1 database in the apac region?"; then
    warn "Database creation cancelled."
    exit 1
  fi
  run_wrangler d1 create leeedwina430-github-io-analytics \
    --location apac \
    --binding DB \
    --use-remote \
    --update-config
fi
run_wrangler d1 migrations apply DB --remote

stage "Deploy the Worker"
say "The first deployment creates the public event endpoint and the private /admin route."
say "On a new Cloudflare account, Wrangler may ask to register a free workers.dev subdomain. Answer yes and choose an available name."
if ! confirm "Deploy the analytics Worker to your Cloudflare account?"; then
  warn "Worker deployment cancelled."
  exit 1
fi
run_wrangler deploy
step "Copy the https://...workers.dev URL printed by Wrangler."
ask ANALYTICS_WORKER_URL "Paste the Worker URL:"
worker_url_pattern='^https://[A-Za-z0-9.-]+\.workers\.dev/?$'
while [[ ! "$ANALYTICS_WORKER_URL" =~ $worker_url_pattern ]]; do
  warn "Enter the base workers.dev URL, without /admin or /api/event."
  ask ANALYTICS_WORKER_URL "Worker URL:"
done
ANALYTICS_WORKER_URL="${ANALYTICS_WORKER_URL%/}"
write_env ANALYTICS_WORKER_URL "$ANALYTICS_WORKER_URL"

stage "Protect the dashboard"
say "Choose credentials for the private analytics dashboard. They are uploaded only as encrypted Worker secrets."
while true; do
  ask ADMIN_USERNAME "Dashboard username (3–40 letters, digits, dot, underscore, or hyphen):"
  if [[ "$ADMIN_USERNAME" =~ ^[A-Za-z0-9._-]{3,40}$ ]]; then break; fi
  warn "That username format is not valid."
done
while true; do
  ask_secret ADMIN_PASSWORD "Dashboard password (at least 16 characters):"
  if (( ${#ADMIN_PASSWORD} < 16 )); then
    warn "Use at least 16 characters."
    continue
  fi
  ask_secret ADMIN_PASSWORD_CONFIRM "Enter the password again:"
  if [[ "$ADMIN_PASSWORD" == "$ADMIN_PASSWORD_CONFIRM" ]]; then break; fi
  warn "The passwords did not match."
done
if command -v openssl >/dev/null 2>&1; then
  IP_HASH_KEY=$(openssl rand -hex 32)
else
  IP_HASH_KEY=$(od -An -N32 -tx1 /dev/urandom | tr -d ' \n')
fi
put_worker_secret ADMIN_USERNAME "$ADMIN_USERNAME"
put_worker_secret ADMIN_PASSWORD "$ADMIN_PASSWORD"
put_worker_secret IP_HASH_KEY "$IP_HASH_KEY"
unset ADMIN_PASSWORD ADMIN_PASSWORD_CONFIRM IP_HASH_KEY
say "Dashboard credentials and the IP rate-limit key are now Cloudflare Worker secrets."

stage "Connect and verify the website"
say "Only the public Worker event URL is written into the website's JavaScript configuration."
bash "$REPO_ROOT/scripts/configure_analytics_endpoint.sh" "$ANALYTICS_WORKER_URL"
health=""
if health=$(curl --fail --silent --show-error "$ANALYTICS_WORKER_URL/health" 2>&1); then
  if [[ "$health" != *'"status":"ok"'* || "$health" != *'"configured":true'* ]]; then
    warn "The health check did not report a fully configured Worker: $health"
    exit 1
  fi
  say "Worker health check passed."
  open_url "$ANALYTICS_WORKER_URL/admin"
  step "Log in with the dashboard username and password you just chose."
  pause "Press Enter after the dashboard opens successfully."
else
  warn "This network could not reach the public workers.dev URL."
  note "curl said: $health"
  say "Checking the deployment, secret names, and D1 binding through Wrangler instead."
  if ! verify_remote_without_public_url; then
    warn "Wrangler could not verify all remote resources."
    exit 1
  fi
  say "Wrangler verified the deployed Worker, required secret names, and D1 binding."
  warn "The dashboard may require another network or a custom domain on this connection."
fi

finish
printf '  Next: run the project tests, review git diff, then publish only the intended changes.\n\n'
